  const formatDate = (dateStr) => {
    if (!dateStr) return "";

    // Remove leading apostrophe if exists
    const clean = String(dateStr).replace(/^'/, "").trim();

    // DD-MM-YYYY validation
    const datePattern = /^([0-2][0-9]|3[0-1])-(0[1-9]|1[0-2])-\d{4}$/;

    return datePattern.test(clean) ? clean : "";
  };

  const GAS_URL =
    "https://script.google.com/macros/s/AKfycby5kltf2lG22accngc-rEdtmTt2PEhBDQz7zrJLT6MBq1giSi0CV0r28aL_uI-EAXuscw/exec";

  const styl = `.ant-modal-root .ant-modal {
    width: var(--ant-modal-xs-width);
    width: 100% !important;
}
.ant-checkbox-checked .ant-checkbox-inner{
    background-color: #0D3884;
    border-color: #0D3884;
}
.ant-checkbox-disabled .ant-checkbox-inner {
    background: rgba(0, 0, 0, 0.04) !important;
    border-color: #d9d9d9 !important;
}`;

  const uploadInstallationPdfToDrive = async (pdfBlob, filename) => {
    const reader = new FileReader();

    reader.onloadend = async () => {
      let base64 = reader.result.split(",")[1];
      base64 = base64.replace(/\s/g, "");

      const payload = new URLSearchParams();
      payload.append("action", "uploadInstallationPDF");
      payload.append("pdfBase64", base64);
      payload.append("filename", filename);

      try {
        const response = await fetch(GAS_URL, {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: payload.toString(),
        });

        // const result = await response.json();

        const text = await response.text();
const result = JSON.parse(text);

        if (result.success) {
          notification.success({
            message: "Success",
            description: "PDF uploaded to Drive successfully!",
            placement: "bottomRight",
            duration: 0,
          });
          // console.log("Drive Link:", result.url);
        } else {
          notification.error({
            message: "Error",
            description: "Failed to upload PDF in Drive: " + result.message,
            placement: "bottomRight",
            duration: 0,
          });
        }
      } catch (error) {
        notification.error({
          message: "Error",
          description: "Network or server error during PDF upload",
          placement: "bottomRight",
          duration: 0,
        });
        // console.error("Upload error:", error);
      }
    };

    reader.readAsDataURL(pdfBlob);
  };

