      installationReportNumber: selectedRecord["Installation Report No"] || "",
      companyName: selectedRecord["Company Name"] || "",
      customerName: selectedRecord["Customer Name"] || "",
      address: selectedRecord["Address"] || "",
      contactNumber: selectedRecord["Contact Number"] || "",
      serviceTechnician: selectedRecord["Service Technician"]
        ? [selectedRecord["Service Technician"]]
        : [],
      // ===== DATES (MUST be dayjs) =====
