      customerDate: formatDate(selectedRecord["Date"]),
      dateOfCommissioning: formatDate(selectedRecord["Date of Commissioning"]),

      // ===== MACHINE DETAILS =====
      makeBrand: selectedRecord["Make/Brand"] || "",
      model: selectedRecord["Model"] || "",
      serialNumber: selectedRecord["Serial Number"] || "",
      capacity: selectedRecord["Capacity (CFM/kW/HP)"] || "",
      voltagePhaseFrequency: selectedRecord["Voltage/Phase/Frequency"] || "",
