      voltageCurrentRecorded: selectedRecord["Voltage/Current Recorded"] || "",
      noiseVibrationLevels: selectedRecord["Noise/Vibration Levels"] || "",

      // ===== PASS / FAIL =====
      noLoadTest: selectedRecord["No-load Test"]
        ? [selectedRecord["No-load Test"]]
        : [],
      loadTest: selectedRecord["Load Test"]
        ? [selectedRecord["Load Test"]]
        : [],
      safetyInterlocksTested: selectedRecord["Safety Interlocks Tested"]
        ? [selectedRecord["Safety Interlocks Tested"]]
        : [],

      // ===== REMARKS =====
      observationRemarks: (
        selectedRecord["Observations & Remarks"] ??
        selectedRecord.observationsRemarks ??
        ""
      ).trim(),
