  const handleExportToExcel = () => {
    if (!customerDataList || customerDataList.length === 0) {
      notification.warning({
        message: "No Data",
        description: "No installation data found.",
        placement: "bottomRight",
      });
      return;
    }

    const headers = Object.keys(customerDataList[0]);

    const sortedData = [...customerDataList].sort((a, b) => {
      const srnDiff =
        Number(a["Installation Report No"] || 0) -
        Number(b["Installation Report No"] || 0);

      if (srnDiff !== 0) return srnDiff;

      return Number(a["S.No"] || 0) - Number(b["S.No"] || 0);
    });

    const excelData = [
      headers,
      ...sortedData.map((row) => headers.map((header) => row[header] ?? "")),
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);

    const range = XLSX.utils.decode_range(worksheet["!ref"]);

    for (let row = range.s.r; row <= range.e.r; row++) {
      for (let col = range.s.c; col <= range.e.c; col++) {
        const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });

        if (!worksheet[cellAddress]) continue;

        // Apply border to all cells
        worksheet[cellAddress].s = {
          border: {
            top: { style: "thin" },
            bottom: { style: "thin" },
            left: { style: "thin" },
            right: { style: "thin" },
          },
        };

        // Header Styling (First Row)
        if (row === 0) {
          worksheet[cellAddress].s = {
            ...worksheet[cellAddress].s,
            fill: {
              patternType: "solid",
              fgColor: { rgb: "FFFF00" }, // Yellow
            },
            font: {
              bold: true,
            },
          };
        }
      }
    }

    worksheet["!cols"] = headers.map(() => ({ wch: 22 }));

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Installation Details");

    XLSX.writeFile(workbook, "Installation_Report.xlsx");

    notification.success({
      message: "Success",
      description: "Installation Report Exported Successfully",
      placement: "bottomRight",
    });
  };

